package com.zerotrust.internalresource.audit; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.slf4j.MDC; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.UUID; @Component("traceRequestContextFilter") public class RequestContextFilter extends OncePerRequestFilter { public static final String TRACE_ID_ATTRIBUTE=RequestContextFilter.class.getName()+".traceId"; protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException { String trace=req.getHeader("X-Trace-Id"); if(trace==null||trace.isBlank()) trace=UUID.randomUUID().toString(); req.setAttribute(TRACE_ID_ATTRIBUTE,trace); res.setHeader("X-Trace-Id",trace); MDC.put("traceId",trace); try{chain.doFilter(req,res);}finally{MDC.remove("traceId");} } }
